import { CardContent, DashboardCard, formatCurrency, formatNumber, PageHeader, SectionHeader, StatCard } from \"@/components/blocks\";
import type { SalesData } from \"@/server/data/sales.types\";

import { RevenueChart } from \"./activity-chart\";
import { TopProductsTable } from \"./records-table\";

export function SalesPage({ data }: { data: SalesData }) {
  const { netRevenue, orders } = data.metrics;
  return (
    <section className=\"min-w-0 space-y-5\" aria-label=\"Sales\">
      <PageHeader title=\"Sales\" description=\"Demo sales · October 19–23, 2026 · All amounts in USD.\" />
      <div className=\"grid gap-4 sm:grid-cols-3\">
        <StatCard label=\"Net revenue\" value={formatCurrency(netRevenue)} help=\"After discounts and returns; excludes tax and shipping.\" />
        <StatCard label=\"Paid orders\" value={formatNumber(orders)} help=\"Orders included in this reporting period.\" />
        <StatCard label=\"Average order value\" value={orders ? formatCurrency(netRevenue / orders, \"USD\", { maximumFractionDigits: 2, minimumFractionDigits: 2 }) : \"—\"} help=\"Net revenue divided by paid orders.\" />
      </div>
      <DashboardCard>
        <SectionHeader title=\"Daily revenue\" description=\"Net revenue across the five-day reporting period.\" />
        <CardContent><RevenueChart data={data.revenue} /></CardContent>
      </DashboardCard>
      <DashboardCard>
        <SectionHeader title=\"Top products\" description=\"All five products sold this period, ranked by net revenue. Orders may include multiple products.\" />
        <CardContent><TopProductsTable products={data.products} /></CardContent>
      </DashboardCard>
    </section>
  );
}
EOF
